import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CWgsre3x.js";const p=JSON.parse('{"title":"Ασφαλής μεταφορά σχεδιασμού ιστοσελίδας","description":"","frontmatter":{},"headers":[],"relativePath":"el/tutorials/website-design-handoff.md","filePath":"el/tutorials/website-design-handoff.md"}'),l={name:"el/tutorials/website-design-handoff.md"};function s(r,e,n,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ασφαλης-μεταφορα-σχεδιασμου-ιστοσελιδας" tabindex="-1">Ασφαλής μεταφορά σχεδιασμού ιστοσελίδας <a class="header-anchor" href="#ασφαλης-μεταφορα-σχεδιασμου-ιστοσελιδας" aria-label="Permalink to &quot;Ασφαλής μεταφορά σχεδιασμού ιστοσελίδας&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="σεναριο-εκπαιδευσης" tabindex="-1">Σενάριο εκπαίδευσης <a class="header-anchor" href="#σεναριο-εκπαιδευσης" aria-label="Permalink to &quot;Σενάριο εκπαίδευσης&quot;">​</a></h2><p>Ο σχεδιαστής ετοιμάζει προσχέδιο σε ξεχωριστό υπολογιστή για έλεγχο από εξουσιοδοτημένο χειριστή. Χρησιμοποιήστε εγκεκριμένες εικόνες και συνθετικό περιεχόμενο.</p><h2 id="βηματα" tabindex="-1">Βήματα <a class="header-anchor" href="#βηματα" aria-label="Permalink to &quot;Βήματα&quot;">​</a></h2><ol><li>Στο Website Studio επιλέξτε τη σωστή ιστοσελίδα και ελέγξτε διαδρομές σελίδων, ενότητες, μενού και μεταφράσεις.</li><li>Ελέγξτε προεπισκόπηση υπολογιστή, tablet, κινητού και στενού κινητού. Εξετάστε τη φόρμα κράτησης, αναδίπλωση κειμένου, εικόνες και πλοήγηση.</li><li>Αποθηκεύστε τοπικά και εξαγάγετε <code>.tbsite.json</code>. Για το οπτικό πρότυπο μόνο, εξαγάγετε <code>.tbtheme.json</code>. Κρατήστε το αρχικό αρχείο ως αντίγραφο.</li><li>Μεταφέρετε το πακέτο με εγκεκριμένο τρόπο και εισαγάγετέ το στο σωστό περιβάλλον. Ελέγξτε την επικύρωση, χωρίς παράκαμψη σφαλμάτων ακεραιότητας ή σχήματος.</li><li>Εξετάστε το εισαγόμενο προσχέδιο και το πεδίο του. Διατηρήστε το αδημοσίευτο μέχρι ξεχωριστή έγκριση.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Επικυρωμένο φορητό προσχέδιο. Η τοπική αποθήκευση δεν αποτελεί συγχρονισμό συσκευών. Η εισαγωγή δεν ενεργοποιεί domain ή ζωντανές κρατήσεις.</p><p>Δείτε <a href="/el/websites/portable-packages.html">Φορητά πακέτα</a> και <a href="/el/websites/publication-controls.html">Έλεγχοι δημοσίευσης</a>.</p>',9)])])}const b=a(l,[["render",s]]);export{p as __pageData,b as default};
